        return httpx.Response(
            200,
            request=request,
            json={
                "id": "chat_fixture",
                "object": "chat.completion",
                "created": 1,
                "model": "other-model",
                "choices": [
                    {
                        "index": 0,
                        "finish_reason": "stop",
                        "message": {"role": "assistant", "content": "ok"},
